// searchPiece (one seed's suffix array search, from ReadAlign::maxMappableLength2strands) must return exactly what the
// upstream code returns: Nrep, maxL and the SA range. Runs on real STAR indices generated by STAR_BIN for a synthetic
// genome with repeats, an N run and a tiny chromosome; a large gSAindexNbases leaves most longer prefixes absent.
#include "Parameters.h"
#include "Genome.h"
#include "SuffixArrayFuns.h"
#include "ErrorWarning.h"
#include "saSearchPiece.h"
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <random>
#include <string>
#include <sys/stat.h>
#include <unistd.h>
#include <vector>

#ifndef STAR_BIN
#error define STAR_BIN as the STAR binary used to generate the test indices
#endif

// ---- upstream STAR 2.7.11b ReadAlign_maxMappableLength2strands.cpp, the body of the iDist loop for iDist=0, verbatim ----
static uint refSearch(Genome &mapGen, Parameters &P, char** Read1, uint pieceStartIn, uint pieceLengthIn, bool dirR,
                      uint& maxL, uint* indStartEnd) {
    uint Nrep=0, iSA1, iSA2, iDist=0;
        uint pieceStart;
        uint pieceLength=pieceLengthIn-iDist;

        //calculate full index
        uint Lmax=min(P.pGe.gSAindexNbases,pieceLength);
        uint ind1=0;
        if (dirR) {//forward search
            pieceStart=pieceStartIn+iDist;
            for (uint ii=0;ii<Lmax;ii++) {//calculate index TODO: make the index calculation once for the whole read and store it
                ind1 <<=2LLU;
                ind1 += ((uint) Read1[0][pieceStart+ii]);
            };
        } else {//reverse search
            pieceStart=pieceStartIn-iDist;
            for (uint ii=0;ii<Lmax;ii++) {//calculate index TODO: make the index calculation once for the whole read and store it
                ind1 <<=2LLU;
                ind1 += ( 3-((uint) Read1[0][pieceStart-ii]) );
            };
        };

        //find SA boundaries
        uint Lind=Lmax;
        while (Lind>0) {//check the presence of the prefix for Lind
            iSA1=mapGen.SAi[mapGen.genomeSAindexStart[Lind-1]+ind1]; // starting point for suffix array search.
            if ((iSA1 & mapGen.SAiMarkAbsentMaskC) == 0) {//prefix exists
                break;
            } else {//this prefix does not exist, reduce Lind
                --Lind;
                ind1 = ind1 >> 2;
            };
        };

        // define upper bound for suffix array range search.
        bool iSA2good = true;
        if (mapGen.genomeSAindexStart[Lind-1]+ind1+1 < mapGen.genomeSAindexStart[Lind]) {//we are not at the end of the SA
            iSA2 = mapGen.SAi[mapGen.genomeSAindexStart[Lind-1]+ind1+1];
            if ( (iSA2 & mapGen.SAiMarkAbsentMaskC) == 0) {
                iSA2 = (iSA2 & mapGen.SAiMarkNmask) - 1;
            } else {
                iSA2 = mapGen.nSA-1; //safe, but can probably do better
                iSA2good = false;
            };
        } else {
            iSA2=mapGen.nSA-1;
            iSA2good = false;
        };

        bool iSA1noN = (iSA1 & mapGen.SAiMarkNmaskC)==0;
        if (Lind < P.pGe.gSAindexNbases && iSA1noN && iSA2good) {//no need for SA search
            // very short seq, already found hits in suffix array w/o having to search the genome for extensions.
            indStartEnd[0]=iSA1;
            indStartEnd[1]=iSA2;
            Nrep=indStartEnd[1]-indStartEnd[0]+1;
            maxL=Lind;
        } else if (iSA1==iSA2 && iSA1noN && iSA2good) {//unique align already, just find maxL
            if ((iSA1 & mapGen.SAiMarkNmaskC)!=0) {
                ostringstream errOut;
                errOut  << "BUG: in ReadAlign::maxMappableLength2strands";
                exitWithError(errOut.str(), std::cerr, P.inOut->logMain, EXIT_CODE_BUG, P);
            };
            indStartEnd[0]=indStartEnd[1]=iSA1;
            Nrep=1;
            bool comparRes;
            maxL=compareSeqToGenome(mapGen, Read1, pieceStart, pieceLength, Lind, iSA1, dirR, comparRes);
        } else {//need SA search, pieceLength>maxL
            if (iSA2good && iSA1noN) {
                maxL = Lind; //Lind bases were already matched
            } else {
                maxL=0;
            };
            Nrep = maxMappableLength(mapGen, Read1, pieceStart, pieceLength, iSA1 & mapGen.SAiMarkNmask, iSA2, dirR, maxL, indStartEnd);
        };
    return Nrep;
}
// ---- end of upstream copy ----

static std::mt19937_64 rng(20261007);
static uint rnd(uint n) { return rng()%n; }

static std::string randomSeq(uint n) {
    std::string s;
    for (uint i=0;i<n;i++) s+="ACGT"[rnd(4)];
    return s;
}

static std::string revComp(const std::string& s) {
    std::string r(s.rbegin(), s.rend());
    for (char& c: r) c= c=='A' ? 'T' : c=='C' ? 'G' : c=='G' ? 'C' : c=='T' ? 'A' : c;
    return r;
}

// copies of other stretches (some exact, some with ~1% substitutions, some reverse-complemented) make deep SA ranges
static std::string withRepeats(std::string s, const std::string& from, uint n, bool rc) {
    for (uint i=0;i<n;i++) {
        uint len=100+rnd(1500), src=rnd(from.size()-len), dst=rnd(s.size()-len);
        std::string piece=from.substr(src, len);
        if (rc) piece=revComp(piece);
        if (i%3) for (char& c: piece) if (rnd(100)==0) c="ACGT"[rnd(4)];
        s.replace(dst, len, piece);
    }
    return s;
}

static void writeFasta(const std::string& path) {
    std::string c1=randomSeq(150000);
    c1=withRepeats(c1, c1, 40, false);
    c1.replace(70000, 120, std::string(120, 'N'));
    c1.replace(90000, 600, std::string(600, 'A'));
    for (uint i=0;i<200;i++) c1.replace(100000+2*i, 2, "AC");
    std::string c2=withRepeats(randomSeq(40000), c1, 20, true);
    std::string c3=randomSeq(37);
    std::ofstream f(path);
    f << ">c1\n" << c1 << "\n>c2\n" << c2 << "\n>c3\n" << c3 << "\n";
}

static uint fileSize(const std::string& p) { struct stat st; return stat(p.c_str(), &st)==0 ? st.st_size : 0; }

static void readInto(const std::string& p, char* buf, uint n) {
    std::ifstream f(p, std::ios::binary);
    f.read(buf, n);
    if ((uint) f.gcount()!=n) { printf("short read of %s\n", p.c_str()); exit(2); }
}

// what Genome::genomeLoad sets up for the fields the SA search reads (NoSharedMemory, no inserted sequences)
static void loadIndex(const std::string& dir, Genome& g, Parameters& P) {
    g.nGenome=fileSize(dir+"/Genome");
    g.nSAbyte=fileSize(dir+"/SA");
    std::ifstream si(dir+"/SAindex", std::ios::binary);
    si.read((char*) &P.pGe.gSAindexNbases, sizeof(P.pGe.gSAindexNbases));
    g.genomeSAindexStart=new uint[P.pGe.gSAindexNbases+1];
    si.read((char*) g.genomeSAindexStart, sizeof(uint)*(P.pGe.gSAindexNbases+1));
    g.nSAi=g.genomeSAindexStart[P.pGe.gSAindexNbases];
    g.GstrandBit=(uint) floor(log(g.nGenome)/log(2))+1;
    if (g.GstrandBit<32) g.GstrandBit=32;
    g.GstrandMask=~(1LLU<<g.GstrandBit);
    g.nSA=(g.nSAbyte*8)/(g.GstrandBit+1);
    g.SA.defineBits(g.GstrandBit+1, g.nSA);
    g.SAiMarkNbit=g.GstrandBit+1;
    g.SAiMarkAbsentBit=g.GstrandBit+2;
    g.SAiMarkNmaskC=1LLU << g.SAiMarkNbit;
    g.SAiMarkNmask=~g.SAiMarkNmaskC;
    g.SAiMarkAbsentMaskC=1LLU << g.SAiMarkAbsentBit;
    g.SAiMarkAbsentMask=~g.SAiMarkAbsentMaskC;
    g.SAi.defineBits(g.GstrandBit+3, g.nSAi);
    const uint L=200, K=6;
    g.G1=new char[g.nGenome+L+L];
    g.G=g.G1+L;
    readInto(dir+"/Genome", g.G, g.nGenome);
    for (uint ii=0;ii<L;ii++) { g.G1[ii]=K-1; g.G[g.nGenome+ii]=K-1; }
    g.SA.allocateArray();
    readInto(dir+"/SA", g.SA.charArray, g.SA.lengthByte);
    g.SAi.allocateArray();
    si.read(g.SAi.charArray, g.SAi.lengthByte);
    if ((uint) si.gcount()!=g.SAi.lengthByte) { printf("short read of SAindex\n"); exit(2); }
}

static void generateIndex(const std::string& dir, const std::string& fasta, uint nbases) {
    std::string cmd=std::string(STAR_BIN)+" --runMode genomeGenerate --runThreadN 2 --genomeDir "+dir
        +" --genomeFastaFiles "+fasta+" --genomeSAindexNbases "+std::to_string(nbases)
        +" --outFileNamePrefix "+dir+"/ > "+dir+"/generate.log 2>&1";
    if (system(cmd.c_str())!=0) { printf("genomeGenerate failed, see %s/generate.log\n", dir.c_str()); exit(2); }
}

// a read of numeric bases: a genome stretch (either strand, ~0-3% substitutions), random, or low complexity
static std::vector<char> makeRead(Genome& g, uint len) {
    std::vector<char> r(len);
    uint kind=rnd(10);
    if (kind<6) {
        uint pos=rnd(g.nGenome-len);
        bool minus=rnd(2);
        uint mut=rnd(4);
        for (uint i=0;i<len;i++) {
            char c= minus ? g.G[pos+len-1-i] : g.G[pos+i];
            if (c>3) c=rnd(4); else if (minus) c=3-c;
            if (mut && rnd(100)<mut) c=rnd(4);
            r[i]=c;
        }
    } else if (kind<8) {
        for (char& c: r) c=rnd(4);
    } else {
        char unit[3]={(char) rnd(4), (char) rnd(4), (char) rnd(4)};
        uint period=1+rnd(3);
        for (uint i=0;i<len;i++) r[i]=unit[i%period];
    }
    return r;
}

static int nFail=0;

// true if the longest SAindex prefix of the piece that is present is followed, at its level, by an absent prefix
static bool nextPrefixAbsent(Genome& g, Parameters& P, char* r, uint start, uint len, bool dirR) {
    uint L=min(P.pGe.gSAindexNbases, len), ind=0;
    for (uint i=0;i<L;i++) ind=(ind<<2) + (dirR ? (uint) r[start+i] : 3-(uint) r[start-i]);
    for (; L>0; L--, ind>>=2) {
        if ((g.SAi[g.genomeSAindexStart[L-1]+ind] & g.SAiMarkAbsentMaskC)==0) break;
    }
    return g.genomeSAindexStart[L-1]+ind+1 < g.genomeSAindexStart[L]
        && (g.SAi[g.genomeSAindexStart[L-1]+ind+1] & g.SAiMarkAbsentMaskC)!=0;
}

// For every present prefix the bound must end its range: one below the SA start of the next present prefix of the same
// length, or nSA-1 if none follows. good is false only for the last prefix of a level, where upstream's bound stands.
static bool testUpperBoundIsNextPresentStart(Genome& g, Parameters& P) {
    nFail=0;
    for (uint L=1; L<=P.pGe.gSAindexNbases; L++) {
        uint nextStart=g.nSA;//SA start of the nearest present prefix after the current one
        for (uint ind=g.genomeSAindexStart[L]-g.genomeSAindexStart[L-1]; ind-- > 0; ) {
            uint e=g.SAi[g.genomeSAindexStart[L-1]+ind];
            if ((e & g.SAiMarkAbsentMaskC)!=0) continue;
            bool last= g.genomeSAindexStart[L-1]+ind+1 == g.genomeSAindexStart[L];
            uint want= last ? g.nSA-1 : nextStart-1;
            bool good;
            uint got=saiUpperBound(g, L, ind, good);
            if (got!=want || good==last) {
                if (nFail++<5) printf("  L=%llu ind=%llu: bound %llu good %d, want %llu good %d\n", L, ind, got, good, want, !last);
            }
            nextStart=e & g.SAiMarkNmask;
        }
    }
    return nFail==0;
}

// minAbsentNext: how many queries must hit a present prefix followed by an absent one (the case a full SAindex lacks)
static bool testSearchPieceMatchesUpstream(Genome& g, Parameters& P, uint nQueries, uint minAbsentNext) {
    nFail=0;
    uint nAbsentNext=0;
    std::vector<char> r0, r1;
    for (uint q=0;q<nQueries;q++) {
        uint len=1+rnd(rnd(4)==0 ? 20 : 150);
        r0=makeRead(g, len);
        r1.resize(len);
        for (uint i=0;i<len;i++) r1[i]=3-r0[i];
        char* Read1[2]={r0.data(), r1.data()};
        bool dirR=rnd(2);
        uint pieceLength=1+rnd(len);
        uint pieceStart= dirR ? rnd(len-pieceLength+1) : pieceLength-1+rnd(len-pieceLength+1);
        if (nextPrefixAbsent(g, P, Read1[0], pieceStart, pieceLength, dirR)) nAbsentNext++;
        uint refL=0, candL=0, refSE[2]={0,0}, candSE[2]={0,0};
        uint refN=refSearch(g, P, Read1, pieceStart, pieceLength, dirR, refL, refSE);
        uint candN=searchPiece(g, Read1, pieceStart, pieceLength, dirR, candL, candSE);
        if (refN!=candN || refL!=candL || refSE[0]!=candSE[0] || refSE[1]!=candSE[1]) {
            if (nFail++<5) printf("  query %llu (len %llu, start %llu, dir %d): upstream Nrep=%llu maxL=%llu [%llu,%llu], "
                "candidate Nrep=%llu maxL=%llu [%llu,%llu]\n", q, pieceLength, pieceStart, dirR,
                refN, refL, refSE[0], refSE[1], candN, candL, candSE[0], candSE[1]);
        }
    }
    if (nAbsentNext<minAbsentNext) {
        printf("  only %llu queries reach a prefix followed by an absent one\n", nAbsentNext);
        nFail++;
    }
    return nFail==0;
}

int main() {
    const char* tmp=getenv("TMPDIR");
    std::string base=std::string(tmp ? tmp : "/tmp")+"/star_saSearch_XXXXXX";
    std::vector<char> dirBuf(base.begin(), base.end()); dirBuf.push_back(0);
    if (!mkdtemp(dirBuf.data())) { printf("mkdtemp failed\n"); return 2; }
    std::string root(dirBuf.data());
    writeFasta(root+"/genome.fa");
    int rc=0;
    for (uint nbases: {11, 7}) {//most 11-mers are absent from this genome, every 7-mer is present
        std::string dir=root+"/idx"+std::to_string(nbases);
        mkdir(dir.c_str(), 0755);
        generateIndex(dir, root+"/genome.fa", nbases);
        Parameters P;
        Genome g(P, P.pGe);
        loadIndex(dir, g, P);
        if (!testUpperBoundIsNextPresentStart(g, P)) {
            printf("FAIL testUpperBoundIsNextPresentStart gSAindexNbases=%llu (%d)\n", nbases, nFail); rc=1;
        }
        if (!testSearchPieceMatchesUpstream(g, P, 400000, nbases==11 ? 20000 : 0)) {
            printf("FAIL testSearchPieceMatchesUpstream gSAindexNbases=%llu (%d)\n", nbases, nFail); rc=1;
        }
    }
    std::string rm="rm -rf "+root;
    if (system(rm.c_str())!=0) printf("could not remove %s\n", root.c_str());
    return rc;
}
